export class BaseDetectionService{options;debugging;session;platform;engine;static NUM_CHANNELS=3;lastDetectionCanvas=null;constructor(platform,session,options={},debugging={},engine="opencv"){this.platform=platform;this.session=session;this.options={...DEFAULT_DETECTION_OPTIONS,...options};this.debugging={...DEFAULT_DEBUGGING_OPTIONS,...debugging};if(engine==="opencv"&&!this.platform.imageProcessor){this.engine="canvas-native"}else{this.engine=engine}}log(message){if(this.debugging.verbose){console.log(`[DetectionService] ${message}`)}}async run(image){this.log("Starting text detection process");try{let canvasToProcess;if(this.platform.isCanvas(image)){canvasToProcess=image}else if(this.engine==="opencv"&&this.platform.imageProcessor){canvasToProcess=await this.platform.imageProcessor.prepareCanvas(image)}else{canvasToProcess=await CanvasProcessor.prepareCanvas(image)}let input=await this.preprocessDetection(canvasToProcess);let detection=await this.runInference(input.tensor,input.width,input.height);if(!detection){console.error("Text detection failed (output tensor is null)");return[]}let detectedBoxes=this.postprocessDetection(detection,input);if(this.debugging.debug&&this.debugging.debugFolder&&this.lastDetectionCanvas){await this.debugDetectionCanvas(this.lastDetectionCanvas,input.width,input.height);await this.debugDetectedBoxes(canvasToProcess,detectedBoxes)}this.log(`Detected ${detectedBoxes.length} text boxes in image`);return detectedBoxes}catch(error){console.error("Error during text detection:",error instanceof Error?error.message:String(error));return[]}}async preprocessDetection(canvas){const{width:originalWidth,height:originalHeight}=canvas;const{width:resizeW,height:resizeH,ratio:resizeRatio}=this.calculateResizeDimensions(originalWidth,originalHeight);let width=Math.ceil(resizeW/32)*32;let height=Math.ceil(resizeH/32)*32;let paddedCanvas=this.platform.createCanvas(width,height);let paddedCtx=paddedCanvas.getContext("2d");paddedCtx.drawImage(canvas,0,0,originalWidth,originalHeight,0,0,resizeW,resizeH);let tensor=this.imageToTensor(paddedCanvas,width,height);this.log(`Detection preprocessed: original(${originalWidth}x${originalHeight}), `+`model_input(${width}x${height}), resize_ratio: ${resizeRatio.toFixed(4)}, engine: ${this.engine}`);return{tensor,width,height,resizeRatio,originalWidth,originalHeight}}calculateResizeDimensions(originalWidth,originalHeight){let MAX_SIDE_LEN=this.options.maxSideLength??960;let resizeW=originalWidth;let resizeH=originalHeight;let ratio=1;if(Math.max(resizeH,resizeW)>MAX_SIDE_LEN){ratio=MAX_SIDE_LEN/(resizeH>resizeW?resizeH:resizeW);resizeW=Math.round(resizeW*ratio);resizeH=Math.round(resizeH*ratio)}return{width:resizeW,height:resizeH,ratio}}imageToTensor(canvas,width,height){let ctx=canvas.getContext("2d");let imageData=ctx.getImageData(0,0,width,height);let rgbaData=imageData.data;let channelSize=height*width;let tensor=new Float32Array(BaseDetectionService.NUM_CHANNELS*channelSize);let mean=this.options.mean??[0.485,0.456,0.406];let stdDeviation=this.options.stdDeviation??[0.229,0.224,0.225];let meanR=mean[0]??0.485;let meanG=mean[1]??0.456;let meanB=mean[2]??0.406;let stdR=stdDeviation[0]??0.229;let stdG=stdDeviation[1]??0.224;let stdB=stdDeviation[2]??0.225;let scaleR=1/(255*stdR);let scaleG=1/(255*stdG);let scaleB=1/(255*stdB);let shiftR=meanR/stdR;let shiftG=meanG/stdG;let shiftB=meanB/stdB;let gOffset=channelSize;let bOffset=channelSize*2;for(let i=0,rgbaIdx=0;i<channelSize;i++,rgbaIdx+=4){let r=rgbaData[rgbaIdx];let g=rgbaData[rgbaIdx+1];let b=rgbaData[rgbaIdx+2];tensor[i]=r*scaleR-shiftR;tensor[gOffset+i]=g*scaleG-shiftG;tensor[bOffset+i]=b*scaleB-shiftB}return tensor}async runInference(tensor,width,height){let inputTensor;try{this.log("Running detection inference...");inputTensor=new this.platform.ort.Tensor("float32",tensor,[1,3,height,width]);let feeds={x:inputTensor};let results=await this.session.run(feeds);let outputTensor=results[this.session.outputNames[0]||"sigmoid_0.tmp_0"];this.log("Detection inference complete!");if(!outputTensor){console.error(`Output tensor ${this.session.outputNames[0]} not found in detection results`);return null}return outputTensor.data}catch(error){console.error("Error during model inference:",error instanceof Error?error.message:String(error));throw error}finally{inputTensor?.dispose()}}tensorToCanvas(tensor,width,height){let canvas=this.platform.createCanvas(width,height);let ctx=canvas.getContext("2d");let imageData=ctx.createImageData(width,height);let data=imageData.data;let totalPixels=width*height;for(let i=0;i<totalPixels;i++){let probability=tensor[i]||0;let grayValue=Math.round(probability*255);let pixelIdx=i*4;data[pixelIdx]=grayValue;data[pixelIdx+1]=grayValue;data[pixelIdx+2]=grayValue;data[pixelIdx+3]=255}ctx.putImageData(imageData,0,0);return canvas}postprocessDetection(detection,input,minBoxAreaOnPadded=this.options.minimumAreaThreshold||20,paddingVertical=this.options.paddingVertical||0.4,paddingHorizontal=this.options.paddingHorizontal||0.6){this.log("Post-processing detection results...");const{width,height,resizeRatio,originalWidth,originalHeight}=input;let canvas=this.tensorToCanvas(detection,width,height);this.lastDetectionCanvas=canvas;if(this.engine==="opencv"&&this.platform.imageProcessor){return this.postprocessWithOpenCV(canvas,width,height,resizeRatio,originalWidth,originalHeight,minBoxAreaOnPadded,paddingVertical,paddingHorizontal)}return this.postprocessWithCanvasNative(canvas,resizeRatio,originalWidth,originalHeight,minBoxAreaOnPadded,paddingVertical,paddingHorizontal)}postprocessWithOpenCV(canvas,width,height,resizeRatio,originalWidth,originalHeight,minBoxAreaOnPadded,paddingVertical,paddingHorizontal){let ip=this.platform.imageProcessor;let processor=new ip.ImageProcessor(canvas);try{processor.grayscale().convert({rtype:ip.cv.CV_8UC1});let contours=new ip.Contours(processor.toMat(),{mode:ip.cv.RETR_LIST,method:ip.cv.CHAIN_APPROX_SIMPLE});let boxes=this.extractBoxesFromContours(contours,width,height,resizeRatio,originalWidth,originalHeight,minBoxAreaOnPadded,paddingVertical,paddingHorizontal);contours.destroy();this.log(`Found ${boxes.length} potential text boxes (opencv)`);return boxes}finally{processor.destroy()}}extractBoxesFromContours(contours,width,height,resizeRatio,originalWidth,originalHeight,minBoxArea,paddingVertical,paddingHorizontal){let boxes=[];contours.iterate((contour)=>{let rect=contours.getRect(contour);if(rect.width*rect.height<=minBoxArea){return}let paddedRect=this.applyPaddingToRect(rect,width,height,paddingVertical,paddingHorizontal);let finalBox=this.convertToOriginalCoordinates(paddedRect,resizeRatio,originalWidth,originalHeight);if(finalBox.width>5&&finalBox.height>5){boxes.push(finalBox)}});return boxes}postprocessWithCanvasNative(canvas,resizeRatio,originalWidth,originalHeight,minBoxAreaOnPadded,paddingVertical,paddingHorizontal){let processor=new CanvasProcessor(canvas).grayscale().threshold({thresh:127});let regions=processor.findRegions({foreground:"light",minArea:minBoxAreaOnPadded,thresh:0,padding:{vertical:paddingVertical,horizontal:paddingHorizontal},scale:1/resizeRatio});let boxes=this.extractBoxesFromRegions(regions,originalWidth,originalHeight);this.log(`Found ${boxes.length} potential text boxes (canvas-native)`);return boxes}extractBoxesFromRegions(regions,originalWidth,originalHeight){let boxes=[];for(let region of regions){const{bbox}=region;let box={x:Math.max(0,bbox.x0),y:Math.max(0,bbox.y0),width:bbox.x1-bbox.x0,height:bbox.y1-bbox.y0};if(box.x+box.width>originalWidth){box.width=originalWidth-box.x}if(box.y+box.height>originalHeight){box.height=originalHeight-box.y}if(box.width>5&&box.height>5){boxes.push(box)}}return boxes}applyPaddingToRect(rect,maxWidth,maxHeight,paddingVertical,paddingHorizontal){let verticalPadding=Math.round(rect.height*paddingVertical);let horizontalPadding=Math.round(rect.height*paddingHorizontal);let x=rect.x-horizontalPadding;let y=rect.y-verticalPadding;let width=rect.width+2*horizontalPadding;let height=rect.height+2*verticalPadding;x=Math.max(0,x);y=Math.max(0,y);let rightEdge=Math.min(maxWidth,rect.x+rect.width+horizontalPadding);let bottomEdge=Math.min(maxHeight,rect.y+rect.height+verticalPadding);width=rightEdge-x;height=bottomEdge-y;return{x,y,width,height}}convertToOriginalCoordinates(rect,resizeRatio,originalWidth,originalHeight){let scaledX=rect.x/resizeRatio;let scaledY=rect.y/resizeRatio;let scaledWidth=rect.width/resizeRatio;let scaledHeight=rect.height/resizeRatio;let x=Math.max(0,Math.round(scaledX));let y=Math.max(0,Math.round(scaledY));let width=Math.min(originalWidth-x,Math.round(scaledWidth));let height=Math.min(originalHeight-y,Math.round(scaledHeight));return{x,y,width,height}}async debugDetectionCanvas(canvas,_width,_height){let dir=this.debugging.debugFolder??"";await this.platform.saveDebugImage(canvas,"detection-debug",dir);this.log(`Probability map visualized and saved to: ${dir}`)}async debugDetectedBoxes(image,boxes){let canvas=this.platform.isCanvas(image)?image:await CanvasProcessor.prepareCanvas(image);let ctx=canvas.getContext("2d");for(let box of boxes){const{x,y,width,height}=box;CanvasToolkit.getInstance().drawLine({ctx,x,y,width,height})}let dir=this.debugging.debugFolder??"";await this.platform.saveDebugImage(canvas,"boxes-debug",dir);this.log(`Boxes visualized and saved to: ${dir}`)}}import{CanvasProcessor,CanvasToolkit}from"ppu-ocv/canvas";import{DEFAULT_DEBUGGING_OPTIONS,DEFAULT_DETECTION_OPTIONS}from"../constants.js";